mapper.sql:
SELECT r.payment_yyyymm , r.employee_no , em.full_name_english AS employee_name , em.org_name_local AS organization_name , DECODE(r.emp_category_code, 'LGD_OW', 'OW', 'LGD_LW', 'LW', r.emp_category_code) AS emp_category_name , r.paid_leave_detail_code , r.tier_no , r.pl_days , r.pl_hours , r.perfect_work_days , r.perfect_work_hours , r.min_wage , r.base_salary_base , r.base_salary_full , r.base_salary_pay , r.base_salary_pay - r.base_salary_full AS base_salary_adj , r.position_allw_base , r.position_allw_full , r.position_allw_pay , r.position_allw_pay - r.position_allw_full AS position_allw_adj , r.job_allw_base , r.job_allw_full , r.job_allw_pay , r.job_allw_pay - r.job_allw_full AS job_allw_adj , r.qualification_allw_base , r.qualification_allw_full , r.qualification_allw_pay , r.qualification_allw_pay - r.qualification_allw_full AS qualification_allw_adj , r.adj1_allw_base , r.adj1_allw_full , r.adj1_allw_pay , r.adj1_allw_pay - r.adj1_allw_full AS adj1_allw_adj , r.adj2_allw_base , r.adj2_allw_full , r.adj2_allw_pay , r.adj2_allw_pay - r.adj2_allw_full AS adj2_allw_adj , r.adj3_allw_base , r.adj3_allw_full , r.adj3_allw_pay , r.adj3_allw_pay - r.adj3_allw_full AS adj3_allw_adj , NVL(r.base_salary_pay,0) + NVL(r.position_allw_pay,0) + NVL(r.job_allw_pay,0) + NVL(r.qualification_allw_pay,0) + NVL(r.adj1_allw_pay,0) + NVL(r.adj2_allw_pay,0) + NVL(r.adj3_allw_pay,0) AS total_pay , TO_CHAR(r.creation_date, 'DD/MM/YYYY HH24:MI') AS calc_date FROM tb_pay_pl_calc_result_n r , emp_master em WHERE em.employee_number = r.employee_no AND r.subsidiary_code = #{LGVHR_PROJECT_SESSION.subsidiaryCode} AND r.payment_yyyymm = #{payMonth}
AND r.paid_leave_detail_code = #{paidLeaveDetailCode}
AND r.employee_no = #{employeeNo}
AND ( UPPER(em.full_name_local) LIKE '%' || UPPER(#{employeeName}) || '%' OR UPPER(em.full_name_english) LIKE '%' || UPPER(#{employeeName}) || '%' )

mapper.select:
SELECT /* LGVPAY00032.retrievePaidLeaveDaily */ d.employee_no , TO_CHAR(d.time_and_attendance_date, 'DD/MM/YYYY') AS att_date , TO_CHAR(d.time_and_attendance_date, 'DY', 'NLS_DATE_LANGUAGE=ENGLISH') AS day_of_week , d.paid_leave_detail_code , DECODE(d.emp_category_code, 'LGD_OW', 'OW', 'LGD_LW', 'LW', d.emp_category_code) AS emp_category_name , d.shift_type_code , TO_CHAR(d.chain_start_date, 'DD/MM/YYYY') AS chain_start_date , d.continuous_days , d.tier_no , d.pl_hours , d.base_amount_type , d.base_salary_rate , d.position_allw_rate , d.job_allw_rate , d.qualification_allw_rate , d.adj1_allw_rate , d.adj2_allw_rate , d.adj3_allw_rate FROM tb_pay_pl_calc_daily_n d WHERE d.subsidiary_code = #{LGVHR_PROJECT_SESSION.subsidiaryCode} AND d.payment_yyyymm = #{payMonth} AND d.employee_no = #{employeeNo}
AND d.paid_leave_detail_code = #{paidLeaveDetailCode}
ORDER BY d.time_and_attendance_date
